{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "opencode-copy-picker",
  "version": "0.1.1",
  "description": "Claude-style picker for copying OpenCode replies, Markdown sections, and code blocks",
  "type": "module",
  "types": "./dist/tui.d.ts",
  "exports": {
    ".": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsup",
    "dev": "tsup --watch",
    "typecheck": "tsc --noEmit",
    "test": "vitest run",
    "test:watch": "vitest",
    "pack:check": "npm pack --dry-run --cache .npm-cache",
    "check": "npm run typecheck && npm test && npm run build && npm run pack:check",
    "prepublishOnly": "npm run check"
  },
  "keywords": [
    "opencode",
    "tui",
    "plugin",
    "clipboard",
    "markdown",
    "copy"
  ],
  "author": "Tomas Janovec",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/tomyjany/opencode-copy-picker.git"
  },
  "bugs": {
    "url": "https://github.com/tomyjany/opencode-copy-picker/issues"
  },
  "homepage": "https://github.com/tomyjany/opencode-copy-picker#readme",
  "publishConfig": {
    "access": "public"
  },
  "packageManager": "pnpm@10.16.1",
  "engines": {
    "node": ">=22.0.0",
    "opencode": ">=1.18.0 <2"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.18.0 <2"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.18.19",
    "@types/node": "^24.3.0",
    "tsup": "^8.5.0",
    "typescript": "^5.9.2",
    "vitest": "^3.2.4"
  }
}
